// Imports the working set of TEI documents from szd-htr into data/ (ADR-010)
// and records their provenance in data/IMPORT.md.
//
// Run: node tools/import-working-set.mjs [path to the szd-htr clone]
//      (default: the sibling directory ../szd-htr; needs git on the PATH)
//
// Files are copied byte-exact (ADR-004). From the import on, this repository
// holds the authoritative copy, so a target that differs from its source has
// been corrected here: the script keeps it and reports it instead of
// overwriting. Most TEI results are gitignored in szd-htr and regenerated by
// its pipeline, so the commit names the pipeline state and the SHA-256 of the
// copied bytes names the exact source.

import { copyFileSync, constants, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { source } from "../js/source.js";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = resolve(process.argv[2] ?? join(REPO, "..", "szd-htr"));
const LIST = join(REPO, "tools", "working-set.json");
const RECORD = join(REPO, "data", "IMPORT.md");
// The collections are the folders js/source.js names.
const COLLECTIONS = new Set(source.collections.map((c) => c.key));
const OBJECT_ID = /^o_szd\.\d+$/;

const git = (...args) =>
  execFileSync("git", ["-C", SOURCE, ...args], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");

if (!existsSync(join(SOURCE, "results"))) throw new Error(`${SOURCE} is not an szd-htr clone (no results/)`);
const commit = git("rev-parse", "HEAD");
const remote = git("remote", "get-url", "origin");
const today = new Date().toISOString().slice(0, 10);
const { documents } = JSON.parse(readFileSync(LIST, "utf8"));

// Rows of an earlier run keep their original commit and date, so a rerun does
// not rewrite the provenance of files imported before.
const previous = new Map();
if (existsSync(RECORD)) {
  for (const line of readFileSync(RECORD, "utf8").split("\n")) {
    const file = line.match(/^\| `o_szd\.\d+` \| \w+ \| `([^`]+)` \|/)?.[1];
    if (file) previous.set(file, line);
  }
}

const rows = [];
const copied = [];
const identical = [];
const kept = [];
const failed = [];
for (const doc of documents) {
  // working-set.json builds file paths, so its values are checked before use.
  if (!OBJECT_ID.test(doc.objectId) || !COLLECTIONS.has(doc.collection)) {
    failed.push(`${doc.objectId}: invalid objectId or collection "${doc.collection}"`);
    continue;
  }
  const relative = `results/${doc.collection}/${doc.objectId}.tei.xml`;
  const source = join(SOURCE, relative);
  const file = doc.target ?? `data/${doc.collection}/${doc.objectId}.tei.xml`;
  if (!/^data\/[\w./-]+\.tei\.xml$/.test(file) || file.includes("..")) {
    failed.push(`${doc.objectId}: target "${file}" is not a TEI file under data/`);
    continue;
  }
  const target = join(REPO, file);
  if (!existsSync(source)) {
    failed.push(`${doc.objectId}: ${relative} not found in ${SOURCE}`);
    continue;
  }
  const bytes = readFileSync(source);
  const text = bytes.toString("utf8");
  const idno = text.match(/<idno type="objectId">([^<]*)<\/idno>/)?.[1];
  if (idno !== doc.objectId || !/<pb\b[^>]*\sfacs="/.test(text)) {
    failed.push(`${doc.objectId}: source lacks idno[@type="objectId"] = ${doc.objectId} or pb/@facs`);
    continue;
  }

  let note;
  if (!existsSync(target)) {
    mkdirSync(dirname(target), { recursive: true });
    copyFileSync(source, target, constants.COPYFILE_EXCL);
    copied.push(file);
    note = "copied";
  } else if (readFileSync(target).equals(bytes)) {
    identical.push(file);
    note = "present before, identical to source";
  } else {
    kept.push(file);
    note = "present before, differs from source";
  }
  if (previous.has(file)) {
    rows.push(previous.get(file));
    continue;
  }
  let tracked = "no";
  try {
    git("ls-files", "--error-unmatch", "--", relative);
    tracked = "yes";
  } catch {
    // ls-files fails for a gitignored or untracked file, which is the normal case for results.
  }
  rows.push(`| \`${doc.objectId}\` | ${doc.collection} | \`${file}\` | ${note} | \`${commit.slice(0, 12)}\` | ${tracked} | ${today} | \`${sha256(bytes)}\` |`);
}

writeFileSync(
  RECORD,
  `# Import record: working set from szd-htr

The TEI documents listed here were copied byte-exact from the szd-htr pipeline by
\`tools/import-working-set.mjs\`, following the selection in \`tools/working-set.json\`.
From their import on they are maintained in this repository (ADR-010); szd-htr receives
no corrections back.

- Source repository: ${remote}, path \`results/<collection>/<objectId>.tei.xml\`.
- Provenance: the szd-htr commit the script read from, whether the file is tracked in
  git there (most TEI results are gitignored and regenerated by the pipeline), the
  import date and the SHA-256 of the copied source bytes, which identifies the
  uncorrected original.
- Content: machine-generated TEI (Page-JSON transcribed by an LLM, converted to TEI),
  structure and transcription unreviewed. The raw HTR markers \`~~…~~\`, \`[?]\`, \`{…}\`
  and \`[...]\` are still plain text.
- Facsimiles are not copied; the editor loads them from the GAMS IIIF manifest
  \`https://gams.uni-graz.at/o:szd.NNNN/sdef:IIIF/getManifest\`.
- Licence: CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/), per the Stefan
  Zweig Digital platform. Attribution: Stefan Zweig Digital, Literaturarchiv Salzburg.

| objectId | collection | file | state at import | szd-htr commit | tracked there | date | SHA-256 of source |
|---|---|---|---|---|---|---|---|
${rows.join("\n")}
`,
);

console.log(`szd-htr ${commit} (${SOURCE})`);
console.log(`Copied: ${copied.length}, identical: ${identical.length}, kept because corrected here: ${kept.length}, failed: ${failed.length}`);
for (const file of kept) console.log(`  kept, differs from source: ${file}`);
for (const message of failed) console.log(`  failed: ${message}`);
console.log(`Record written to ${RECORD}`);
if (failed.length) process.exitCode = 1;
